# %% pts/tests/02_storage/test_backends.pct.py 2
import os
import tempfile
import pytest

from netrun.storage._backends import (
    LocalBackend,
    validate_backend_imports,
)

# %% pts/tests/02_storage/test_backends.pct.py 4
def test_local_write_and_read():
    """Write and read data from a local backend."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        backend.write("test/data.bin", b"hello world")
        result = backend.read("test/data.bin")
        assert result == b"hello world"


def test_local_exists():
    """Check existence of a key."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        assert not backend.exists("missing.bin")
        backend.write("present.bin", b"data")
        assert backend.exists("present.bin")


def test_local_delete():
    """Delete a key."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        backend.write("to_delete.bin", b"data")
        assert backend.exists("to_delete.bin")
        backend.delete("to_delete.bin")
        assert not backend.exists("to_delete.bin")


def test_local_read_missing_raises():
    """Reading a non-existent key should raise FileNotFoundError."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        with pytest.raises(FileNotFoundError):
            backend.read("missing.bin")


def test_local_nested_directories():
    """Writing to nested paths should auto-create parent directories."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        backend.write("a/b/c/deep.bin", b"deep data")
        result = backend.read("a/b/c/deep.bin")
        assert result == b"deep data"


def test_local_overwrite():
    """Writing to an existing key should overwrite."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        backend.write("file.bin", b"version1")
        backend.write("file.bin", b"version2")
        assert backend.read("file.bin") == b"version2"


def test_local_binary_data():
    """Backend should handle arbitrary binary data."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        data = bytes(range(256))
        backend.write("binary.bin", data)
        assert backend.read("binary.bin") == data


def test_local_empty_data():
    """Backend should handle empty bytes."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        backend.write("empty.bin", b"")
        assert backend.read("empty.bin") == b""


def test_local_large_data():
    """Backend should handle reasonably large data."""
    with tempfile.TemporaryDirectory() as tmpdir:
        backend = LocalBackend(tmpdir)
        data = b"x" * (1024 * 1024)  # 1MB
        backend.write("large.bin", data)
        assert backend.read("large.bin") == data

# %% pts/tests/02_storage/test_backends.pct.py 6
def test_validate_local_backend_imports():
    """Local backend has no external deps, should always pass."""
    validate_backend_imports("local")
